-- MySQL 8.0.16+; all demo policies are fictional. Execute in an empty database.
SET NAMES utf8mb4;
CREATE TABLE community(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,district VARCHAR(80) NOT NULL,area_code VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE organization(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,community_id BIGINT NOT NULL,FOREIGN KEY(community_id) REFERENCES community(id));
CREATE TABLE account(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role ENUM('ADMIN','FAMILY','CAREGIVER','MANAGER','STREET','REGULATOR') NOT NULL,community_id BIGINT NOT NULL,organization_id BIGINT,failures INT NOT NULL DEFAULT 0,locked_until DATETIME,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(community_id) REFERENCES community(id),FOREIGN KEY(organization_id) REFERENCES organization(id));
CREATE TABLE elder(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(60) NOT NULL,identity_hash CHAR(64) NOT NULL UNIQUE,identity_cipher TEXT NOT NULL,birth_date DATE NOT NULL,address VARCHAR(200) NOT NULL,community_id BIGINT NOT NULL,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',FOREIGN KEY(community_id) REFERENCES community(id));
CREATE TABLE elder_tag(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,tag ENUM('ALONE','DISABLED','LOW_INCOME') NOT NULL,UNIQUE(elder_id,tag),FOREIGN KEY(elder_id) REFERENCES elder(id));
CREATE TABLE guardian(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,account_id BIGINT NOT NULL,relation_name VARCHAR(30) NOT NULL,phone_cipher TEXT NOT NULL,UNIQUE(elder_id,account_id),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(account_id) REFERENCES account(id));
CREATE TABLE assessment(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,scale_name VARCHAR(50) NOT NULL,score INT NOT NULL,ability_level ENUM('SELF','PARTIAL','SEVERE') NOT NULL,assessor_id BIGINT NOT NULL,assessed_at DATETIME NOT NULL,valid_until DATETIME NOT NULL,CHECK(score BETWEEN 0 AND 100),CHECK(valid_until>assessed_at),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(assessor_id) REFERENCES account(id),INDEX idx_assessment_elder(elder_id,valid_until));
CREATE TABLE service_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,category VARCHAR(30) NOT NULL,unit ENUM('VISIT','HOUR') NOT NULL,price DECIMAL(10,2) NOT NULL,duration_minutes INT NOT NULL,subsidizable BOOLEAN NOT NULL,CHECK(price>=0),CHECK(duration_minutes>0));
CREATE TABLE care_bundle(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,ability_level ENUM('SELF','PARTIAL','SEVERE') NOT NULL);
CREATE TABLE bundle_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,bundle_id BIGINT NOT NULL,item_id BIGINT NOT NULL,weekly_frequency INT NOT NULL,CHECK(weekly_frequency>0),UNIQUE(bundle_id,item_id),FOREIGN KEY(bundle_id) REFERENCES care_bundle(id),FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE caregiver(id BIGINT PRIMARY KEY AUTO_INCREMENT,account_id BIGINT NOT NULL UNIQUE,organization_id BIGINT NOT NULL,name VARCHAR(60) NOT NULL,status ENUM('ACTIVE','LEAVE','LEFT') NOT NULL DEFAULT 'ACTIVE',FOREIGN KEY(account_id) REFERENCES account(id),FOREIGN KEY(organization_id) REFERENCES organization(id));
CREATE TABLE credential(id BIGINT PRIMARY KEY AUTO_INCREMENT,caregiver_id BIGINT NOT NULL,item_id BIGINT NOT NULL,certificate_no VARCHAR(80) NOT NULL UNIQUE,certificate_level VARCHAR(30) NOT NULL,valid_from DATETIME NOT NULL,valid_until DATETIME NOT NULL,CHECK(valid_until>valid_from),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE caregiver_area(id BIGINT PRIMARY KEY AUTO_INCREMENT,caregiver_id BIGINT NOT NULL,community_id BIGINT NOT NULL,UNIQUE(caregiver_id,community_id),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),FOREIGN KEY(community_id) REFERENCES community(id));
CREATE TABLE care_plan(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,assessment_id BIGINT NOT NULL,bundle_id BIGINT NOT NULL,caregiver_id BIGINT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,status ENUM('ACTIVE','PAUSED','EXPIRED','ENDED') NOT NULL DEFAULT 'ACTIVE',CHECK(ends_at>starts_at),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(assessment_id) REFERENCES assessment(id),FOREIGN KEY(bundle_id) REFERENCES care_bundle(id),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),INDEX idx_plan_elder(elder_id,status,starts_at,ends_at));
CREATE TABLE plan_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,item_id BIGINT NOT NULL,weekly_frequency INT NOT NULL,CHECK(weekly_frequency>0),UNIQUE(plan_id,item_id),FOREIGN KEY(plan_id) REFERENCES care_plan(id),FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE shift(id BIGINT PRIMARY KEY AUTO_INCREMENT,caregiver_id BIGINT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,capacity INT NOT NULL,used_count INT NOT NULL DEFAULT 0,status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN',CHECK(ends_at>starts_at),CHECK(capacity>0 AND used_count>=0 AND used_count<=capacity),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),INDEX idx_shift_caregiver(caregiver_id,starts_at,ends_at));
CREATE TABLE service_order(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,item_id BIGINT NOT NULL,community_id BIGINT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,address VARCHAR(200) NOT NULL,channel ENUM('PHONE','FAMILY','COMMUNITY') NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('PENDING','ASSIGNED','ACCEPTED','SERVING','CONFIRM','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING',created_by BIGINT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_at>starts_at),CHECK(amount>=0),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(item_id) REFERENCES service_item(id),FOREIGN KEY(community_id) REFERENCES community(id),FOREIGN KEY(created_by) REFERENCES account(id),INDEX idx_order_status_time(status,starts_at),INDEX idx_order_elder(elder_id,starts_at));
CREATE TABLE dispatch(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,caregiver_id BIGINT NOT NULL,shift_id BIGINT NOT NULL,status ENUM('WAITING','ACCEPTED','FINISHED','REASSIGNED','REJECTED') NOT NULL DEFAULT 'WAITING',reason VARCHAR(200) NOT NULL DEFAULT '首次派单',assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,accepted_at DATETIME,active_order BIGINT GENERATED ALWAYS AS (CASE WHEN status IN ('WAITING','ACCEPTED') THEN order_id ELSE NULL END) STORED,UNIQUE(active_order),FOREIGN KEY(order_id) REFERENCES service_order(id),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),FOREIGN KEY(shift_id) REFERENCES shift(id),INDEX idx_dispatch_worker(caregiver_id,status));
CREATE TABLE service_record(id BIGINT PRIMARY KEY AUTO_INCREMENT,dispatch_id BIGINT NOT NULL UNIQUE,notes VARCHAR(1000) NOT NULL,confirmed_by BIGINT,confirmed_at DATETIME,confirmation VARCHAR(300),FOREIGN KEY(dispatch_id) REFERENCES dispatch(id),FOREIGN KEY(confirmed_by) REFERENCES account(id));
CREATE TABLE attendance(id BIGINT PRIMARY KEY AUTO_INCREMENT,dispatch_id BIGINT NOT NULL UNIQUE,check_in DATETIME NOT NULL,check_out DATETIME,location_note VARCHAR(200) NOT NULL,fence_ok BOOLEAN NOT NULL,status ENUM('PENDING','REVIEW','VALID','INVALID') NOT NULL DEFAULT 'PENDING',effective_minutes INT NOT NULL DEFAULT 0,reviewer_id BIGINT,review_reason VARCHAR(300),CHECK(check_out IS NULL OR check_out>check_in),CHECK(effective_minutes>=0),FOREIGN KEY(dispatch_id) REFERENCES dispatch(id),FOREIGN KEY(reviewer_id) REFERENCES account(id));
CREATE TABLE device(id BIGINT PRIMARY KEY AUTO_INCREMENT,serial_no VARCHAR(80) NOT NULL UNIQUE,type_name VARCHAR(50) NOT NULL,location_note VARCHAR(200) NOT NULL,status ENUM('ACTIVE','OFFLINE','RETIRED') NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE device_binding(id BIGINT PRIMARY KEY AUTO_INCREMENT,device_id BIGINT NOT NULL,elder_id BIGINT NOT NULL,bound_at DATETIME NOT NULL,unbound_at DATETIME,active_device BIGINT GENERATED ALWAYS AS (CASE WHEN unbound_at IS NULL THEN device_id ELSE NULL END) STORED,UNIQUE(active_device),CHECK(unbound_at IS NULL OR unbound_at>bound_at),FOREIGN KEY(device_id) REFERENCES device(id),FOREIGN KEY(elder_id) REFERENCES elder(id));
CREATE TABLE metric_rule(id BIGINT PRIMARY KEY AUTO_INCREMENT,metric VARCHAR(60) NOT NULL UNIQUE,low_value DECIMAL(12,3) NOT NULL,high_value DECIMAL(12,3) NOT NULL,response_seconds INT NOT NULL,CHECK(high_value>low_value),CHECK(response_seconds>0));
CREATE TABLE vital(id BIGINT PRIMARY KEY AUTO_INCREMENT,binding_id BIGINT NOT NULL,metric_rule_id BIGINT NOT NULL,sample_key VARCHAR(80) NOT NULL,collected_at DATETIME NOT NULL,metric_value DECIMAL(12,3) NOT NULL,abnormal BOOLEAN NOT NULL DEFAULT FALSE,source VARCHAR(50) NOT NULL,UNIQUE(binding_id,sample_key),FOREIGN KEY(binding_id) REFERENCES device_binding(id),FOREIGN KEY(metric_rule_id) REFERENCES metric_rule(id));
CREATE TABLE emergency(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,vital_id BIGINT UNIQUE,source VARCHAR(50) NOT NULL,level INT NOT NULL DEFAULT 1,occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deadline DATETIME NOT NULL,status ENUM('UNCONFIRMED','OPEN','RESPONDED','CLOSED','FALSE_ALARM') NOT NULL,responded_by BIGINT,responded_at DATETIME,arrived_at DATETIME,result VARCHAR(1000),CHECK(level BETWEEN 1 AND 3),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(vital_id) REFERENCES vital(id),FOREIGN KEY(responded_by) REFERENCES account(id),INDEX idx_emergency_deadline(status,deadline));
CREATE TABLE emergency_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,level INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,message VARCHAR(300) NOT NULL,UNIQUE(event_id,level),FOREIGN KEY(event_id) REFERENCES emergency(id));
CREATE TABLE notification(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,account_id BIGINT NOT NULL,message VARCHAR(300) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(event_id,account_id,message),FOREIGN KEY(event_id) REFERENCES emergency(id),FOREIGN KEY(account_id) REFERENCES account(id));
CREATE TABLE policy(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,community_id BIGINT NOT NULL,item_id BIGINT NOT NULL,ability_level ENUM('SELF','PARTIAL','SEVERE') NOT NULL,rate DECIMAL(10,2) NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,CHECK(rate>=0),CHECK(ends_at>starts_at),FOREIGN KEY(community_id) REFERENCES community(id),FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE claim(id BIGINT PRIMARY KEY AUTO_INCREMENT,elder_id BIGINT NOT NULL,policy_id BIGINT NOT NULL,item_id BIGINT NOT NULL,period CHAR(7) NOT NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('DRAFT','SUBMITTED','STREET_APPROVED','APPROVED','REJECTED','PAID') NOT NULL DEFAULT 'DRAFT',UNIQUE(elder_id,item_id,period),CHECK(amount>=0),FOREIGN KEY(elder_id) REFERENCES elder(id),FOREIGN KEY(policy_id) REFERENCES policy(id),FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE claim_item(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL,order_id BIGINT NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,effective_minutes INT NOT NULL,rate_snapshot DECIMAL(10,2) NOT NULL,CHECK(amount>=0 AND effective_minutes>0),FOREIGN KEY(claim_id) REFERENCES claim(id),FOREIGN KEY(order_id) REFERENCES service_order(id));
CREATE TABLE claim_review(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL,reviewer_id BIGINT NOT NULL,stage ENUM('STREET','REGULATOR') NOT NULL,decision ENUM('APPROVE','REJECT') NOT NULL,reason VARCHAR(300) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(claim_id) REFERENCES claim(id),FOREIGN KEY(reviewer_id) REFERENCES account(id));
CREATE TABLE payment(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_id BIGINT NOT NULL UNIQUE,reference_no VARCHAR(80) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(amount>0),FOREIGN KEY(claim_id) REFERENCES claim(id));
CREATE TABLE inspection(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT,caregiver_id BIGINT,inspector_id BIGINT NOT NULL,method ENUM('PHONE','VISIT') NOT NULL,score INT NOT NULL,issue VARCHAR(300) NOT NULL,rectification VARCHAR(300) NOT NULL,status ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN',result VARCHAR(300),CHECK((order_id IS NULL)<>(caregiver_id IS NULL)),CHECK(score BETWEEN 0 AND 100),FOREIGN KEY(order_id) REFERENCES service_order(id),FOREIGN KEY(caregiver_id) REFERENCES caregiver(id),FOREIGN KEY(inspector_id) REFERENCES account(id));
CREATE TABLE complaint(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,account_id BIGINT NOT NULL,rating INT NOT NULL,content VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(order_id) REFERENCES service_order(id),FOREIGN KEY(account_id) REFERENCES account(id));
CREATE TABLE audit_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,table_name VARCHAR(50) NOT NULL,row_id BIGINT NOT NULL,operation VARCHAR(20) NOT NULL,actor VARCHAR(100) NOT NULL,old_status VARCHAR(100),new_status VARCHAR(100),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_object(table_name,row_id));
